        for m in range(a + 1):
            if n == 0 or m == 0:
                OPT[n][m] = 0
            elif before_l[n - 1][1] == after_l[m - 1][1]:
                OPT[n][m] = OPT[n - 1][m - 1] + 1
            else:
                OPT[n][m] = max(OPT[n][m - 1], OPT[n - 1][m])

    output = []
