                neighbor = self.find_node(neighbor_id)
                if neighbor is None:
                    continue
                if neighbor.id in recursion_stack:
                    raise ValueError("Graph is not acyclic")
                if neighbor.id not in visited:
                    dfs(neighbor)

            recursion_stack.remove(node.id)
            result.insert(0, node)

