import numpy as np

class Vector(ABC):
    def __init__(self, *args: int):
        self.vals = args

    @abstractmethod
    def manhattan_distance(other) -> float:
        pass

    @abstractmethod
    def cosine_similarity(other) -> float:
        pass

class MyVector(Vector):
    def __init__(self, *args: int):
        super().__init__(*args)

    def manhattan_distance(self, other: Vector) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same dimension")
        return float(np.sum(np.abs(np.array(self.vals) - np.array(other.vals))))

    def cosine_similarity(self, other: Vector) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same dimension")

        a = np.array(self.vals)
        b = np.array(other.vals)

        magnitude_a = np.linalg.norm(a)
        magnitude_b = np.linalg.norm(b)

        if magnitude_a == 0 or magnitude_b == 0:
            raise ValueError("Cannot compute cosine similarity with zero magnitude vector")

        return float(np.dot(a, b) / (magnitude_a * magnitude_b))

