import numpy as np

class Vector(ABC):
    def __init__(self, *args: int):
        self.vals = args

    @abstractmethod
    def manhattan_distance(other) -> float:
        pass

    @abstractmethod
    def cosine_similarity(other) -> float:
        pass

class MyVector(Vector):
    def __init__(self, *args: int):
        super().__init__(*args)

    def manhattan_distance(self, other: Vector) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same dimension")

        distance = sum(abs(x - y) for x, y in zip(self.vals, other.vals))
        return float(distance)

    def cosine_similarity(self, other: Vector) -> float:
        if len(self.vals) != len(other.vals):
            raise ValueError("Vectors must have the same dimension")

        a = np.array(self.vals)
        b = np.array(other.vals)

        magnitude_a = np.linalg.norm(a)
        magnitude_b = np.linalg.norm(b)

        if magnitude_a == 0 or magnitude_b == 0:
            raise ValueError("Cannot compute cosine similarity with zero vector")

        cos_sim = np.dot(a, b) / (magnitude_a * magnitude_b)
        return float(np.arccos(cos_sim))

class Sorter:
    def __init__(self):
        pass

    def sort(self, nums: list[int]) -> None:
        self.insertion_sort(nums)

    def insertion_sort(self, nums: list[int]) -> None:
        for i in range(1, len(nums)):
            key = nums[i]
            j = i-1
            while j >= 0 and key < nums[j] :
                nums[j + 1] = nums[j]
                j -= 1
            nums[j + 1] = key

