                    stack.append(operand1 - operand2)
                elif token == "*":
                    stack.append(operand1 * operand2)
                elif token == "/":
                    stack.append(operand1 / operand2)
                else:
                    raise Exception("Malformed input")

        if len(stack) != 1:
            raise Exception("Malformed input")

        return stack[0]

