from typing import Literal, List

Op = Literal["+", "-", "*", "/"]
Token = int | Op


class PostfixParser:
    def parse(self, inputs: List[Token]) -> float:
        """parses a sequence of input tokens using postfix notation and computes the result"""

        stack: List[float] = []
        for token in inputs:
            if isinstance(token, int):
                stack.append(float(token))
            elif token in ("+", "-", "*", "/"):
                if len(stack) < 2:
                    raise Exception("Malformed input: insufficient operands for operator")
                operand2 = stack.pop()
                operand1 = stack.pop()
                if token == "+":
                    stack.append(operand1 + operand2)
                elif token == "-":
                    stack.append(operand1 - operand2)
                elif token == "*":
                    stack.append(operand1 * operand2)
                elif token == "/":
                    if operand2 == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(operand1 / operand2)
            else:
                raise ValueError(f"Invalid token: {token}")

        if len(stack) != 1:
            raise Exception("Malformed input: too many operands remaining")

        return stack[0]

