        if P == (None, None) or k == 0:
            return (None, None)

        # Precompute powers of P
        powers = [P]
        for i in range(1, 2**w):
            powers.append(self.point_addition(powers[-1], P))

        # Convert k to binary representation
        binary_k = bin(k)[2:]

        # Pad with leading zeros to make length a multiple of w
        padding = (w - len(binary_k) % w) % w
        binary_k = '0' * padding + binary_k

        result = (None, None)
        for i in range(0, len(binary_k), w):
            window = binary_k[i:i+w]
            window_int = int(window, 2)

            if window_int != 0:
                result = self.point_addition(result, powers[window_int - 1])

            if i + w < len(binary_k):
                for _ in range(w):
                    result = self.point_double(result)

        return result

    def generate_keypair(self, G: tuple, n: int, d : int) -> tuple:
        """ Given an initial point G and an order n, construct a keypair, and d, the private key """
        assert 1 <= d and d <= n-1
        Q = self.windowed_point_multiplication(d, G) # public key
        return (d, Q) 

    def validate_keypair(self, d: int, Q: tuple, G: tuple, n: int) -> bool:
        """ Validate the given keypair, given an initial point G,
            a public key Q, a private key d, and a group order n """
        if not (1 <= d < n) : return False
        if not self.is_on_curve(Q[0], Q[1]) : return False
        return self.windowed_point_multiplication(d, G) == Q
